50	template<bool zero_init=true, typename Engine0, typename Layout0, typename Engine1, typename Layout1>
51	__device__ __forceinline__ void reduce_max(Tensor<Engine0, Layout0> const& tensor, Tensor<Engine1, Layout1> &max){
52	    MaxOp<float> max_op;
53	    reduce_<zero_init>(tensor, max, max_op);
54	}
