56	template<bool zero_init=true, bool warp_reduce=true, typename Engine0, typename Layout0, typename Engine1, typename Layout1>
57	__device__ __forceinline__ void reduce_sum(Tensor<Engine0, Layout0> const& tensor, Tensor<Engine1, Layout1> &sum){
58	    SumOp<float> sum_op;
59	    thread_reduce_<zero_init>(tensor, sum, sum_op);
60	    if constexpr (warp_reduce) { quad_allreduce_(sum, sum, sum_op); }
61	}
62	
63	// Apply the exp to all the elements.
64	template <bool Scale_max=true, bool Check_inf=true, int Max_offset=0,
65	        typename Engine0, typename Layout0, typename Engine1, typename Layout1>
66	__forceinline__ __device__ void scale_apply_exp2(Tensor<Engine0, Layout0> &tensor, Tensor<Engine1, Layout1> const &max, const float scale) {
67	    // For FP8, we can subtract max by 8.0 so that the value after exp2 is in the range of [0, 256].
68	    // This lets us use more of the FP8 range (instead of just [0, 1]) to reduce underflow.
69	    static constexpr float max_offset = float(Max_offset);  // We can only template on int, not float
70	    static_assert(Layout0::rank == 2, "Only support 2D Tensor");
71	    static_assert(Layout1::rank == 1, "Only support 1D Tensor");
72	    CUTE_STATIC_ASSERT_V(size<0>(max) == size<0>(tensor));
73	    #pragma unroll
74	    for (int mi = 0; mi < size<0>(tensor); ++mi) {
75	        // If max is -inf, then all elements must have been -inf (possibly due to masking).
76	        // We don't want (-inf - (-inf)) since that would give NaN.
77	        const float max_scaled = Check_inf
78	            ? (max(mi) == -INFINITY ? 0.f : (!Scale_max ? max(mi) : max(mi) * scale) - max_offset)
79	            : (!Scale_max ? max(mi) : max(mi) * scale) - max_offset;
80	        #pragma unroll
81	        for (int ni = 0; ni < size<1>(tensor); ++ni)  {
82	            // Instead of computing exp(x - max), we compute exp2(x * log_2(e) -
83	            // max * log_2(e)). This allows the compiler to use the ffma
84	            // instruction instead of fadd and fmul separately.
85	            tensor(mi, ni) = exp2f(tensor(mi, ni) * scale - max_scaled);
86	        }
87	    }
88	}
89	
90	////////////////////////////////////////////////////////////////////////////////////////////////////
91	
92	template <int kNRows, int Max_offset=0>
93	struct Softmax {
94	
95	    using TensorT = decltype(make_tensor<float>(Shape<Int<kNRows>>{}));
96	    TensorT row_max, row_sum;
97	    float const softmax_scale_log2;
98	
99	    CUTLASS_DEVICE Softmax(float const softmax_scale_log2_) : softmax_scale_log2(softmax_scale_log2_) {};
100	
101	    template<bool Is_first, bool Check_inf=false, typename Tensor0>
102	    __forceinline__ __device__ TensorT max_get_scale(Tensor0 &acc_s) {
103	        // Reshape acc_s from ((2, 2, V), MMA_M, MMA_N) to (nrow=(2, MMA_M), ncol=(2, V, MMA_N))
104	        Tensor scores = make_tensor(acc_s.data(), flash::convert_layout_acc_rowcol(acc_s.layout()));
105	        static_assert(CUTE_STATIC_V(size<0>(scores)) == kNRows);
106	        TensorT scores_scale;
107	        if constexpr (Is_first) {
108	            flash::template reduce_max</*zero_init=*/true>(scores, row_max);
109	            cute::fill(scores_scale, 1.f);
110	        } else {
111	            Tensor scores_max_prev = make_fragment_like(row_max);
112	            cute::copy(row_max, scores_max_prev);
113	            flash::template reduce_max</*zero_init=*/false>(scores, row_max);
114	            #pragma unroll
115	            for (int mi = 0; mi < size(row_max); ++mi) {
116	                float scores_max_cur = !Check_inf
117	                    ? row_max(mi)
118	                    : (row_max(mi) == -INFINITY ? 0.0f : row_max(mi));
119	                scores_scale(mi) = exp2f((scores_max_prev(mi) - scores_max_cur) * softmax_scale_log2);
120	                row_sum(mi) *= scores_scale(mi);
121	            }
122	        }
123	        return scores_scale;
124	    };
125	
126	    template<bool Is_first, bool Check_inf=false, typename Tensor0>
127	    __forceinline__ __device__ void online_softmax(Tensor0 &acc_s) {
128	        // Reshape acc_s from ((2, 2, V), MMA_M, MMA_N) to (nrow=(2, MMA_M), ncol=(2, V, MMA_N))
129	        Tensor scores = make_tensor(acc_s.data(), flash::convert_layout_acc_rowcol(acc_s.layout()));
130	        static_assert(CUTE_STATIC_V(size<0>(scores)) == kNRows);
131	        flash::template scale_apply_exp2</*Scale_max=*/true, Check_inf, Max_offset>(scores, row_max, softmax_scale_log2);
132	        // We don't do the reduce across threads here since we don't need to use the row_sum.
133	        // We do that reduce at the end when we need to normalize the softmax.
134	        flash::reduce_sum</*zero_init=*/Is_first, /*warp_reduce=*/false>(scores, row_sum);
135	    };
136	
137	    __forceinline__ __device__ TensorT finalize(float const final_scale=1.f) {
138	        SumOp<float> sum_op;
139	        quad_allreduce_(row_sum, row_sum, sum_op);
140	        TensorT scores_scale;
141	        #pragma unroll
142	        for (int mi = 0; mi < size(row_sum); ++mi) {
143	            float sum = row_sum(mi);
144	            float inv_sum = (sum == 0.f || sum != sum) ? 0.f : 1.f / sum;
145	            scores_scale(mi) = inv_sum * final_scale;
146	            // For FP8, we might have scaled the output of exp by 2**8 so we need to divide sum by that amount.
147	            if constexpr (Max_offset != 0) {
148	                static constexpr float sum_scale = 1.f / float(1 << Max_offset);
149	                sum *= sum_scale;
150	            }
151	            row_sum(mi) = (sum == 0.f || sum != sum) ? -INFINITY : row_max(mi) * (softmax_scale_log2 * float(M_LN2)) + __logf(sum);
152	        }
153	        return scores_scale;
154	    };
155	
156	    __forceinline__ __device__ TensorT finalize_aux(TensorT const& tSrSAux, float const final_scale=1.f) {
157	        SumOp<float> sum_op;
158	        quad_allreduce_(row_sum, row_sum, sum_op);
159	        TensorT scores_scale;
160	        #pragma unroll
161	        for (int mi = 0; mi < size(row_sum); ++mi) {
162	            if (row_max(mi) == -INFINITY) { row_max(mi) = 0.f; }
163	            const float max_scaled = row_max(mi) * softmax_scale_log2 - Max_offset;
164	            float sum = row_sum(mi) + exp2f(float(M_LOG2E) * tSrSAux(mi) - max_scaled);
165	            float inv_sum = (sum == 0.f || sum != sum) ? 0.f : 1.f / sum;
166	            scores_scale(mi) = inv_sum * final_scale;
167	            // For FP8, we might have scaled the output of exp by 2**8 so we need to divide sum by that amount.
168	            if constexpr (Max_offset != 0) {
169	                static constexpr float sum_scale = 1.f / float(1 << Max_offset);
170	                sum *= sum_scale;
171	            }
172	            row_sum(mi) = (sum == 0.f || sum != sum) ? -INFINITY : row_max(mi) * (softmax_scale_log2 * float(M_LN2)) + __logf(sum);
173	        }
174	        return scores_scale;
175	    };
176	
177	    template<typename Tensor1>
178	    __forceinline__ __device__ void rescale_o(Tensor1 &acc_o, TensorT const &scores_scale) {
179	        // Reshape acc_o from (MMA=4, MMA_M, MMA_K) to (nrow=(2, MMA_M), ncol=(2, MMA_K))
180	        Tensor acc_o_rowcol = make_tensor(acc_o.data(), flash::convert_layout_acc_rowcol(acc_o.layout()));
181	        static_assert(CUTE_STATIC_V(size<0>(acc_o_rowcol)) == kNRows);
182	        #pragma unroll
183	        for (int mi = 0; mi < size<0>(acc_o_rowcol); ++mi) {
184	            #pragma unroll
185	            for (int ni = 0; ni < size<1>(acc_o_rowcol); ++ni) { acc_o_rowcol(mi, ni) *= scores_scale(mi); }
186	        }
187	    };
188	
189	};
190	
191	}  // namespace flash
